fn draw_list(f: &mut ratatui::Frame, app: &mut App, area: Rect) {
    let rows = app.visible_rows();
    let inner = pane_inner(area);
    fill_area(f.buffer_mut(), area, theme_base_style());
    let cols = list_columns(inner.width);
    debug_assert!(inner.width < 20 || cols.row_width() == inner.width as usize);
    let selected = app.list_state.selected();
    let items: Vec<ListItem> = rows
        .iter()
        .enumerate()
        .map(|(idx, row)| {
            let s = row.info;
            let agent_state = app.agent_state_for(s);
            let prov = prov_span(s.provider);
            let title = s.title.as_deref().unwrap_or("");
            let age = age_label(s.updated_at_epoch_s);
            let marker = if selected == Some(idx) { "▶ " } else { "  " };
            let session_label = if app.session_view == SessionViewMode::Tree {
                tree_session_label(row.depth, &s.session_id)
            } else {
                session_id_display_label(&s.session_id)
            };
            let mut spans = vec![
                Span::raw(marker),
                Span::styled(
                    fit_width(agent_state.label(), cols.state, Align::Left),
                    agent_state.style(),
                ),
                Span::raw(" "),
                prov,
            ];
            if cols.title > 0 {
                spans.push(Span::raw(" "));
                spans.push(Span::styled(
                    fit_width(title, cols.title, Align::Left),
                    Style::default().fg(THEME_FG_STRONG),
                ));
            }
            if cols.age > 0 {
                spans.push(Span::raw(" "));
                spans.push(Span::styled(
                    fit_width(&age, cols.age, Align::Right),
                    Style::default().fg(THEME_FG_DIM),
                ));
            }
            if cols.cwd > 0 {
                spans.push(Span::raw(" "));
                spans.push(Span::styled(
                    fit_width(&s.cwd, cols.cwd, Align::Left),
                    Style::default().fg(THEME_FG_DIM),
                ));
            }
            spans.extend([
                Span::raw(" "),
                Span::styled(
                    fit_width(&session_label, cols.id, Align::Left),
                    Style::default().fg(THEME_FG_DIM),
                ),
            ]);
            let line = Line::from(spans);
            ListItem::new(line)
        })
        .collect();

    let title = format!(
        " sessions [{}] {} {} {} ",
        rows.len(),
        app.provider_filter.label(),
        app.session_view.label(),
        if app.text_filter.is_empty() {
            String::new()
        } else {
            format!("search={}", app.text_filter)
        },
    );
    let block = Block::default()
        .borders(Borders::ALL)
        .border_style(focus_style(app.focus == FocusPane::Sessions))
        .style(theme_base_style())
        .title(title);
    f.render_widget(block, area);

    if inner.height == 0 {
        return;
    }

    let header = fit_width(&list_header(&cols), inner.width as usize, Align::Left);
    f.buffer_mut().set_stringn(
        inner.x,
        inner.y,
        header,
        inner.width as usize,
        Style::default()
            .fg(THEME_FG_DIM)
            .bg(THEME_BG)
            .add_modifier(Modifier::BOLD),
    );

    if inner.height <= 1 {
        return;
    }

    let list_area = Rect::new(
        inner.x,
        inner.y.saturating_add(1),
        inner.width,
        inner.height.saturating_sub(1),
    );
    let list = List::new(items)
        .style(theme_base_style())
        .highlight_style(theme_selected_style());
    f.render_stateful_widget(list, list_area, &mut app.list_state);
}

fn draw_preview(f: &mut ratatui::Frame, app: &mut App, area: Rect) {
    let inner = pane_inner(area);
    fill_area(f.buffer_mut(), area, theme_base_style());
    app.preview_page_height = inner.height.max(1);

    let current = app.current().cloned();
    let mut lines = Vec::new();
    let mut summary_style_state = PreviewSummaryStyleState::default();
    let mut max_scroll = 0u16;
    let title = if inner.width < MIN_PREVIEW_WRAP_WIDTH {
        app.preview_scroll = 0;
        " preview ".to_string()
    } else if let Some(info) = current {
        let key = PreviewKey::new(&info, app.preview_mode);
        app.request_preview(info.clone(), key.clone(), inner.width as usize);
        if let Some(line_count) = app.ensure_wrapped_preview(&key, inner.width as usize) {
            max_scroll = line_count
                .saturating_sub(inner.height as usize)
                .min(u16::MAX as usize) as u16;
            if app.preview_scroll > max_scroll {
                app.preview_scroll = max_scroll;
            }
            summary_style_state =
                app.preview_summary_style_state_before(&key, app.preview_scroll as usize);
            lines =
                app.preview_visible_lines(&key, app.preview_scroll as usize, inner.height as usize);
        } else {
            app.preview_scroll = 0;
            lines.push(format!(
                "loading {} session {}",
                info.provider.as_str(),
                truncate_width(&info.session_id, 14)
            ));
        }
        let loading = app
            .preview_requested
            .as_ref()
            .map(|(requested_key, _)| requested_key == &key)
            .unwrap_or(false);
        format!(
            " preview {} {} {}/{}{} ",
            info.provider.as_str(),
            truncate_width(&info.session_id, 14),
            app.preview_scroll,
            max_scroll,
            if loading { " *" } else { "" }
        )
    } else {
        app.preview_scroll = 0;
        " preview ".to_string()
    };
    let block = Block::default()
        .borders(Borders::ALL)
        .border_style(focus_style(app.focus == FocusPane::Preview))
        .style(theme_base_style())
        .title(title);
    f.render_widget(block, area);

    let buf = f.buffer_mut();
    fill_area(buf, inner, theme_base_style());
    let styled_lines: Vec<Line> = lines
        .iter()
        .take(inner.height as usize)
        .scan(summary_style_state, |state, line| {
            Some(preview_line_with_state(line, app.preview_mode, state))
        })
        .collect();
    f.render_widget(
        Paragraph::new(styled_lines).style(theme_base_style()),
        inner,
    );
}

#[derive(Debug, Default, Clone, Copy)]
struct PreviewSummaryStyleState {
    body_context: PreviewSummaryBodyContext,
}

#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
enum PreviewSummaryBodyContext {
    #[default]
    Plain,
    ToolUseArgs,
    ToolResult,
    Patch,
}

fn preview_line_with_state(
    line: &str,
    mode: Mode,
    state: &mut PreviewSummaryStyleState,
) -> Line<'static> {
    if mode != Mode::Summary {
        return Line::from(Span::styled(line.to_string(), theme_base_style()));
    }
    let styled = preview_summary_line_with_context(line, state.body_context);
    preview_summary_update_style_state_after_line(state, line);
    styled
}

#[cfg(test)]
fn preview_summary_line(line: &str) -> Line<'static> {
    preview_summary_line_with_context(line, PreviewSummaryBodyContext::Plain)
}

fn preview_summary_line_with_context(
    line: &str,
    body_context: PreviewSummaryBodyContext,
) -> Line<'static> {
    if line.is_empty() {
        return Line::from(Span::raw(""));
    }
    if matches!(line, "Session" | "Messages") {
        return Line::from(preview_bold_span(line, THEME_ACCENT));
    }
    for (prefix, color) in [
        ("USER #", THEME_PREVIEW_USER),
        ("ASSISTANT #", THEME_PREVIEW_ASSISTANT),
        ("TOOL #", THEME_PREVIEW_TOOL),
        ("SYSTEM #", THEME_PREVIEW_SYSTEM),
        ("DEVELOPER #", THEME_PREVIEW_DEVELOPER),
    ] {
        if line.starts_with(prefix) {
            return preview_summary_role_line(line, prefix, color);
        }
    }
    for (label, color) in [
        ("  thinking", THEME_PREVIEW_THINKING),
        ("  tool use", THEME_PREVIEW_TOOL),
        ("  image", THEME_PREVIEW_IMAGE),
        ("  attachment", THEME_PREVIEW_ATTACHMENT),
        ("  patch", THEME_PREVIEW_PATCH_HEADER),
        ("  other", THEME_PREVIEW_OTHER),
        ("  input text", THEME_PREVIEW_USER),
        ("  output text", THEME_PREVIEW_ASSISTANT),
    ] {
        if preview_summary_label_matches(line, label) {
            return preview_summary_prefix_line(line, label, color);
        }
    }
    if preview_summary_label_matches(line, "  tool result") {
        return preview_summary_tool_result_line(line);
    }
    if preview_summary_field_split(line).is_some() {
        return preview_summary_field_line(line);
    }
    preview_summary_body_line(line, body_context)
}

fn preview_summary_update_style_state_after_line(state: &mut PreviewSummaryStyleState, line: &str) {
    if preview_summary_label_matches(line, "  patch") {
        state.body_context = PreviewSummaryBodyContext::Patch;
    } else if preview_summary_label_matches(line, "  tool use") {
        state.body_context = PreviewSummaryBodyContext::ToolUseArgs;
    } else if preview_summary_label_matches(line, "  tool result") {
        state.body_context = PreviewSummaryBodyContext::ToolResult;
    } else if preview_summary_line_starts_new_block(line)
        || (line.is_empty() && state.body_context != PreviewSummaryBodyContext::ToolResult)
    {
        state.body_context = PreviewSummaryBodyContext::Plain;
    }
}

fn preview_summary_style_states_for_lines(lines: &[String]) -> Vec<PreviewSummaryStyleState> {
    let mut states = Vec::with_capacity(lines.len().saturating_add(1));
    let mut state = PreviewSummaryStyleState::default();
    states.push(state);
    for line in lines {
        preview_summary_update_style_state_after_line(&mut state, line);
        states.push(state);
    }
    states
}

fn preview_summary_line_starts_new_block(line: &str) -> bool {
    matches!(line, "Session" | "Messages")
        || ["USER #", "ASSISTANT #", "TOOL #", "SYSTEM #", "DEVELOPER #"]
            .iter()
            .any(|prefix| line.starts_with(prefix))
        || [
            "  thinking",
            "  tool use",
            "  image",
            "  attachment",
            "  other",
            "  input text",
            "  output text",
            "  tool result",
        ]
        .iter()
        .any(|label| preview_summary_label_matches(line, label))
        || preview_summary_field_split(line).is_some()
}

fn preview_summary_label_matches(line: &str, label: &str) -> bool {
    let Some(rest) = line.strip_prefix(label) else {
        return false;
    };
    rest.is_empty() || rest.starts_with(':') || rest.starts_with(" · ") || rest.starts_with(" [")
}

fn preview_summary_tool_result_is_error(line: &str) -> bool {
    line.rsplit(" · ")
        .next()
        .is_some_and(|status| status == "error")
}

fn preview_summary_field_split(line: &str) -> Option<usize> {
    const SUMMARY_FIELD_LABEL_WIDTH: usize = 8;
    let split = 2 + SUMMARY_FIELD_LABEL_WIDTH;
    let bytes = line.as_bytes();
    if !line.starts_with("  ") || line.starts_with("    ") || bytes.get(split) != Some(&b':') {
        return None;
    }
    let label = line.get(2..split)?.trim();
    matches!(
        label,
        "provider"
            | "id"
            | "title"
            | "cwd"
            | "model"
            | "git"
            | "tokens"
            | "created"
            | "updated"
            | "messages"
    )
    .then_some(split + 1)
}

fn preview_summary_role_line(line: &str, prefix: &str, color: Color) -> Line<'static> {
    let head_end = line
        .find(" · ")
        .unwrap_or_else(|| line.len())
        .max(prefix.len());
    let (head, tail) = line.split_at(head_end);
    if let Some(hash_idx) = head.find('#') {
        let (role, id) = head.split_at(hash_idx);
        let mut spans = vec![
            preview_bold_span(role, color),
            preview_bold_span(id, THEME_PREVIEW_ID),
        ];
        spans.extend(preview_value_spans(tail, THEME_FG_DIM));
        return Line::from(spans);
    }
    let mut spans = vec![preview_bold_span(head, color)];
    spans.extend(preview_value_spans(tail, THEME_FG_DIM));
    Line::from(spans)
}

fn preview_summary_prefix_line(line: &str, prefix: &str, color: Color) -> Line<'static> {
    let split = line
        .find(':')
        .map(|idx| idx + 1)
        .unwrap_or_else(|| prefix.len().min(line.len()));
    let (head, tail) = line.split_at(split);
    let mut spans = vec![preview_bold_span(head, color)];
    spans.extend(preview_value_spans(tail, THEME_FG_STRONG));
    Line::from(spans)
}

fn preview_summary_tool_result_line(line: &str) -> Line<'static> {
    let status_color = if preview_summary_tool_result_is_error(line) {
        THEME_PREVIEW_ERROR
    } else {
        THEME_POSITIVE
    };
    let split = line
        .find(':')
        .map(|idx| idx + 1)
        .unwrap_or_else(|| "  tool result".len().min(line.len()));
    let (head, tail) = line.split_at(split);
    let mut spans = vec![preview_bold_span(head, status_color)];
    if let Some((details, status)) = tail.rsplit_once(" · ") {
        spans.extend(preview_value_spans(details, THEME_FG_STRONG));
        spans.push(preview_span(" · ", THEME_FG_DIM));
        spans.push(preview_span(status, status_color));
    } else {
        spans.extend(preview_value_spans(tail, THEME_FG_STRONG));
    }
    Line::from(spans)
}

fn preview_summary_field_line(line: &str) -> Line<'static> {
    let Some(split) = preview_summary_field_split(line) else {
        return Line::from(preview_span(line, THEME_FG));
    };
    let (label, value) = line.split_at(split);
    let mut spans = vec![preview_span(label, THEME_PREVIEW_FIELD)];
    spans.extend(preview_value_spans(
        value,
        preview_summary_field_value_color(label, value),
    ));
    Line::from(spans)
}

fn preview_summary_body_line(line: &str, body_context: PreviewSummaryBodyContext) -> Line<'static> {
    let trimmed = line.trim_start();
    if body_context == PreviewSummaryBodyContext::ToolResult {
        return Line::from(preview_span(line, THEME_FG));
    }

    if body_context == PreviewSummaryBodyContext::Patch {
        let color = if trimmed.starts_with("+++") || trimmed.starts_with("---") {
            THEME_PREVIEW_PATCH_HEADER
        } else if trimmed.starts_with('+') {
            THEME_POSITIVE
        } else if trimmed.starts_with('-') {
            THEME_PREVIEW_PATCH_REMOVE
        } else if trimmed.starts_with("@@") {
            THEME_PREVIEW_PATCH_HEADER
        } else if trimmed.starts_with("... +")
            || trimmed.starts_with("(no ")
            || trimmed == "(empty)"
        {
            THEME_FG_DIM
        } else {
            THEME_FG
        };
        return Line::from(preview_span(line, color));
    }

    if body_context == PreviewSummaryBodyContext::ToolUseArgs {
        if preview_summary_indent_width(line) == 4 {
            if let Some(split) = line.find(':').filter(|idx| *idx > 4) {
                return preview_summary_key_value_line_plain_value(line, split, THEME_PREVIEW_KEY);
            }
        }
        return Line::from(preview_span(line, THEME_FG));
    }

    let color =
        if trimmed.starts_with("... +") || trimmed.starts_with("(no ") || trimmed == "(empty)" {
            THEME_FG_DIM
        } else {
            THEME_FG
        };

    Line::from(preview_span(line, color))
}

fn preview_summary_indent_width(line: &str) -> usize {
    line.bytes().take_while(|byte| *byte == b' ').count()
}

fn preview_summary_key_value_line_plain_value(
    line: &str,
    split: usize,
    label_color: Color,
) -> Line<'static> {
    let (label, value) = line.split_at(split + 1);
    Line::from(vec![
        preview_span(label, label_color),
        preview_span(value, THEME_FG),
    ])
}

fn preview_summary_field_value_color(label: &str, value: &str) -> Color {
    let label = label.trim().trim_end_matches(':').trim();
    match label {
        "provider" => provider_color_from_summary_line(value).unwrap_or(THEME_FG_STRONG),
        "id" => THEME_PREVIEW_ID,
        "cwd" => THEME_PREVIEW_PATH,
        "model" => THEME_PREVIEW_DEVELOPER,
        "git" => THEME_PREVIEW_PATCH_HEADER,
        "tokens" => THEME_POSITIVE,
        "created" | "updated" => THEME_PREVIEW_TIME,
        "messages" => THEME_ACCENT,
        _ => THEME_FG_STRONG,
    }
}

fn preview_value_spans(text: &str, default_color: Color) -> Vec<Span<'static>> {
    let mut spans = Vec::new();
    let mut rest = text;
    const PREVIEW_DETAIL_SEPARATOR: &str = " · ";
    while let Some(separator) = rest.find(PREVIEW_DETAIL_SEPARATOR) {
        let (segment, after_segment) = rest.split_at(separator);
        push_preview_segment_spans(&mut spans, segment, default_color);
        spans.push(preview_span(PREVIEW_DETAIL_SEPARATOR, THEME_FG_DIM));
        rest = &after_segment[PREVIEW_DETAIL_SEPARATOR.len()..];
    }
    push_preview_segment_spans(&mut spans, rest, default_color);
    spans
}

fn push_preview_segment_spans(spans: &mut Vec<Span<'static>>, segment: &str, default_color: Color) {
    let mut rest = segment;
    while let Some(open) = rest.find('[') {
        let (before, after_open) = rest.split_at(open);
        push_preview_plain_span(spans, before, default_color);
        if let Some(close) = after_open.find(']') {
            let (id, after_id) = after_open.split_at(close + 1);
            spans.push(preview_span(id, THEME_FG_DIM));
            rest = after_id;
        } else {
            push_preview_plain_span(spans, after_open, default_color);
            return;
        }
    }
    push_preview_plain_span(spans, rest, default_color);
}

fn push_preview_plain_span(spans: &mut Vec<Span<'static>>, text: &str, default_color: Color) {
    if text.is_empty() {
        return;
    }
    spans.push(preview_span(text, default_color));
}

fn provider_color_from_summary_line(value: &str) -> Option<Color> {
    match value.trim() {
        "claude" => Some(THEME_PROVIDER_CLAUDE),
        "codex" => Some(THEME_PROVIDER_CODEX),
        "opencode" => Some(THEME_PROVIDER_OPENCODE),
        _ => None,
    }
}

fn preview_style(color: Color) -> Style {
    Style::default().fg(color).bg(THEME_BG)
}

fn preview_span(text: impl Into<String>, color: Color) -> Span<'static> {
    Span::styled(text.into(), preview_style(color))
}

fn preview_bold_span(text: impl Into<String>, color: Color) -> Span<'static> {
    Span::styled(
        text.into(),
        preview_style(color).add_modifier(Modifier::BOLD),
    )
}

fn pane_inner(area: Rect) -> Rect {
    Rect::new(
        area.x.saturating_add(1),
        area.y.saturating_add(1),
        area.width.saturating_sub(2),
        area.height.saturating_sub(2),
    )
}

fn fill_area(buf: &mut Buffer, area: Rect, style: Style) {
    let area = area.intersection(buf.area);
    for y in area.top()..area.bottom() {
        for x in area.left()..area.right() {
            buf[(x, y)].reset();
            buf[(x, y)].set_style(style);
        }
    }
}

fn draw_status(f: &mut ratatui::Frame, app: &mut App, area: Rect) {
    fill_area(f.buffer_mut(), area, theme_status_style());
    let width = area.width as usize;
    let help = truncate_width(&help_text(app.focus, width, &app.keybindings), width);
    let mode = format!(
        "{} focus · {} preview",
        match app.focus {
            FocusPane::Sessions => "sessions",
            FocusPane::Preview => "preview",
        },
        preview_mode_label(app.preview_mode)
    );
    let mode = truncate_width(&mode, width);
    let mode_width = UnicodeWidthStr::width(mode.as_str());
    let status_width = width.saturating_sub(mode_width + 2);
    let status_text = app.display_status();
    let status = truncate_width(&status_text, status_width);
    let mut status_spans = vec![Span::styled(
        mode,
        Style::default().fg(THEME_SHORTCUT).bg(THEME_STATUS_BG),
    )];
    if !status.is_empty() {
        status_spans.push(Span::raw("  "));
        status_spans.push(Span::styled(
            status,
            Style::default().fg(THEME_ACCENT).bg(THEME_STATUS_BG),
        ));
    }
    let lines = vec![
        Line::from(status_spans),
        Line::from(Span::styled(
            help,
            Style::default().fg(THEME_FG_DIM).bg(THEME_STATUS_BG),
        )),
    ];
    f.render_widget(Paragraph::new(lines).style(theme_status_style()), area);
}

