    #[test]
    fn cokacdir_start_failure_keeps_notice_dialog_open() {
        let dir = tempfile::tempdir().unwrap();
        let cwd = dir.path().display().to_string();
        let missing_program = dir.path().join(cokacdir_local_filename());
        let mut app = app_for_key_tests();
        let (tx, rx) = mpsc::channel::<MainEvent>();
        app.main_tx = Some(tx);
        app.settings.cokacmux.cokacdir_program = Some(missing_program.display().to_string());
        app.input_mode = InputMode::NewSession {
            selected: NEW_SESSION_FIELD_KIND,
            kind: NewSessionKind::CokacDir,
            cwd: cwd.clone(),
            cwd_cursor: cwd.len(),
            provider: Provider::Codex,
            provider_options: vec![Provider::Codex],
            launch_mode: AgentLaunchMode::Normal,
        };

        let keybindings = app.keybindings.clone();
        handle_new_session_key(
            &mut app,
            KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE),
            80,
            24,
            &keybindings,
        );

        // The cokacdir program check runs in the attach worker's prepare
        // stage; the failure dialog opens when its result is applied.
        assert!(matches!(app.input_mode, InputMode::Normal));
        pump_attach_result(&mut app, &rx);

        match &app.input_mode {
            InputMode::Notice { title, message } => {
                assert_eq!(title, "cokacdir failed");
                assert!(message.contains("configured cokacdir_program"));
                assert!(message.contains(&missing_program.display().to_string()));
            }
            other => panic!("expected notice dialog, got {other:?}"),
        }
    }

    #[test]
    fn keybinding_file_change_reloads_via_watcher_check() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("keybinding.json");
        fs::write(
            &path,
            r#"{"sessions":{"launch_agent":["x"],"toggle_view":["z"]}}"#,
        )
        .unwrap();

        let mut app = app_for_key_tests();
        app.sessions
            .push(session_info(Provider::Codex, "codex-id", "/repo"));
        app.list_state.select(Some(0));

        let mut known_mtime = None;
        let reload = check_keybindings_reload(Some(&path), &mut known_mtime)
            .expect("changed file should produce a reload");
        app.on_keybindings_reloaded(reload);
        assert!(known_mtime.is_some());

        // The default binding no longer launches; the custom one does.
        handle_key(
            &mut app,
            KeyEvent::new(KeyCode::Char('e'), KeyModifiers::NONE),
            100,
            80,
            20,
        );
        assert!(matches!(app.input_mode, InputMode::Normal));

        handle_key(
            &mut app,
            KeyEvent::new(KeyCode::Char('x'), KeyModifiers::NONE),
            100,
            80,
            20,
        );
        assert!(matches!(app.input_mode, InputMode::AgentLaunch { .. }));

        // Unchanged file produces no further reloads.
        assert!(check_keybindings_reload(Some(&path), &mut known_mtime).is_none());
    }

    #[test]
    fn deleted_keybinding_file_is_recreated_by_watcher_check() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("keybinding.json");
        fs::write(&path, r#"{"sessions":{"launch_agent":["x"]}}"#).unwrap();
        let (keybindings, mut known_mtime) = KeyBindings::load_with_mtime(Some(&path));
        fs::remove_file(&path).unwrap();

        let mut app = app_for_key_tests();
        app.keybindings = keybindings;
        app.sessions
            .push(session_info(Provider::Codex, "codex-id", "/repo"));
        app.list_state.select(Some(0));

        let reload = check_keybindings_reload(Some(&path), &mut known_mtime)
            .expect("missing file should be recreated and reloaded");
        app.on_keybindings_reloaded(reload);

        assert!(path.exists());
        // Recreated defaults restore the default launch binding.
        handle_key(
            &mut app,
            KeyEvent::new(KeyCode::Char('e'), KeyModifiers::NONE),
            100,
            80,
            20,
        );
        assert!(matches!(app.input_mode, InputMode::AgentLaunch { .. }));
    }

