        let shift_key = KeyEvent::new(KeyCode::Up, KeyModifiers::SHIFT);
        let ctrl_shift_key =
            KeyEvent::new(KeyCode::Down, KeyModifiers::CONTROL | KeyModifiers::SHIFT);
