        safe_parser_process(&mut source, b"\x1b[?1049h\x1b[H\x1b[2JA\r\nB\r\nC\r\nD");
        history.capture(&mut source);
        safe_parser_process(&mut source, b"\x1b[H\x1b[2JB\r\nC\r\nD\r\nE");
